<section class="container section"><p class="eyebrow">COMUNICACIÓN PRIVADA</p><h1>Solicitudes recibidas</h1><p>Revisa las consultas y registra su estado de atención.</p><?php require ROOT . '/app/Views/errors.php'; ?><?php if (!$requests): ?><p class="empty">Todavía no hay solicitudes recibidas.</p><?php endif; ?>
<div class="request-list"><?php foreach ($requests as $request): ?><article class="form-panel"><div class="section-head"><h2>#<?= e($request['id']) ?> · <?= e($request['nombre_adulto']) ?></h2><span class="badge"><?= e($request['estado']) ?></span></div><p><strong><?= e($request['tipo']) ?></strong> · <?= e($request['contacto']) ?></p><p class="muted">Recibida: <?= e($request['creado_en']) ?> · hora de Colombia</p><p class="prose"><?= nl2br(e($request['mensaje'])) ?></p><small>Aceptación registrada: <?= e($request['consentimiento_version']) ?></small><form method="post" action="<?= e(url('admin/solicitudes')) ?>" data-submit data-confirm="¿Actualizar el estado de esta solicitud?"><?= csrf() ?><input type="hidden" name="id" value="<?= e($request['id']) ?>"><label for="estado-<?= e($request['id']) ?>">Estado de la solicitud #<?= e($request['id']) ?></label><div class="actions"><select name="estado" id="estado-<?= e($request['id']) ?>"><?php foreach (['pendiente', 'revisada', 'cerrada'] as $state): ?><option <?= $state === $request['estado'] ? 'selected' : '' ?> value="<?= e($state) ?>"><?= e(ucfirst($state)) ?></option><?php endforeach; ?></select><button class="button" type="submit">Actualizar estado</button></div></form></article><?php endforeach; ?></div><div class="actions pager"><?php if ($page > 1): ?><a href="<?= e(url('admin/solicitudes', ['page' => $page - 1])) ?>">Anterior</a><?php endif; ?><?php if ($more): ?><a href="<?= e(url('admin/solicitudes', ['page' => $page + 1])) ?>">Siguiente</a><?php endif; ?></div></section>
